package com.phoenix.business;import org.junit.jupiter.params.ParameterizedTest;import org.junit.jupiter.params.provider.ValueSource;import static org.junit.jupiter.api.Assertions.*;
class PasswordPolicyTest {private static final String POLICY="^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d).{10,72}$";@ParameterizedTest @ValueSource(strings={"StrongPass1","AnotherSecure9Value"})void acceptsStrongPasswords(String value){assertTrue(value.matches(POLICY));}@ParameterizedTest @ValueSource(strings={"short1A","alllowercase1","ALLUPPERCASE1","NoDigitsHere"})void rejectsWeakPasswords(String value){assertFalse(value.matches(POLICY));}}
